import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { UI_SLOTS, type UiSlotSpec } from "@capybara-hq/plugin-sdk";
import type { Finding } from "./source.js";

export type { Finding };

/** Where the generated files live, relative to the repository root. */
export const UI_SLOTS_TS = "apps/web/src/lib/ui-slots.generated.ts";
export const UI_SLOTS_DOC = "docs/guide/ui-slots.md";

const union = (values: readonly string[]) => values.map((v) => JSON.stringify(v)).join(" | ");
const list = (values: readonly string[]) => `[${values.map((v) => JSON.stringify(v)).join(", ")}]`;

/** The generated web copy of the slot catalog (the web app never imports the SDK). */
export function renderUiSlotsTs(slots: readonly UiSlotSpec[]): string {
  const scopes = [...new Set(slots.map((s) => s.scope))];
  const entries = slots.map((s) =>
    [
      `  ${JSON.stringify(s.id)}: {`,
      `    scope: ${JSON.stringify(s.scope)},`,
      `    accepts: ${list(s.accepts)},`,
      `    minRole: ${JSON.stringify(s.minRole)},`,
      `    args: ${list(s.args)},`,
      `    density: ${JSON.stringify(s.density)},`,
      `    anchors: ${list(s.anchors ?? [])},`,
      "  },",
    ].join("\n"),
  );
  return [
    "// Generated by pnpm gen:ui-slots from @capybara-hq/plugin-sdk; do not edit.",
    "",
    `export type UiSlotId =\n  | ${slots.map((s) => JSON.stringify(s.id)).join("\n  | ")};`,
    "",
    `export type UiSlotScope = ${union(scopes)};`,
    "",
    "export const UI_SLOT_SPECS: Record<",
    "  UiSlotId,",
    "  {",
    "    scope: UiSlotScope;",
    "    accepts: readonly string[];",
    "    minRole: string;",
    "    args: readonly string[];",
    "    density: string;",
    "    anchors: readonly string[];",
    "  }",
    "> = {",
    ...entries,
    "};",
    "",
  ].join("\n");
}

const code = (values: readonly string[]) =>
  values.length === 0 ? "none" : values.map((v) => `\`${v}\``).join(", ");

/** The generated docs page: a table of every slot and a section per slot. */
export function renderUiSlotsDoc(slots: readonly UiSlotSpec[]): string {
  const rows = slots.map(
    (s) =>
      `| \`${s.id}\` | ${s.scope} | ${code(s.accepts)} | ${s.minRole} | ${code(s.args)} | ${s.density} |`,
  );
  const sections = slots.map((s) =>
    [
      `## \`${s.id}\``,
      "",
      s.description.en,
      "",
      `- Version: ${s.version}`,
      `- Scope: ${s.scope}`,
      `- Accepts: ${code(s.accepts)}`,
      `- Minimum role: ${s.minRole}`,
      `- Args: ${code(s.args)}`,
      `- Density: ${s.density}`,
      `- Anchors: ${code(s.anchors ?? [])}`,
      `- Owner: \`apps/web/src/${s.owner}\``,
      "",
    ].join("\n"),
  );
  return [
    "<!-- Generated by pnpm gen:ui-slots from @capybara-hq/plugin-sdk; do not edit. -->",
    "",
    "# UI slots",
    "",
    "The places in the web app where extension UI can appear. Each slot has an id, a scope, the kinds",
    "of UI it accepts, the lowest role that sees it and the arguments it passes to the contribution.",
    "",
    "| Slot | Scope | Accepts | Min role | Args | Density |",
    "|---|---|---|---|---|---|",
    ...rows,
    "",
    ...sections,
  ].join("\n");
}

/**
 * check:ui-slots: the generated web copy and docs page equal what gen:ui-slots renders from the SDK
 * catalog (`ui-slots-stale`).
 */
export function checkUiSlots(root: string): Finding[] {
  const out: Finding[] = [];
  for (const [rel, expected] of [
    [UI_SLOTS_TS, renderUiSlotsTs(UI_SLOTS)],
    [UI_SLOTS_DOC, renderUiSlotsDoc(UI_SLOTS)],
  ] as const) {
    const file = join(root, rel);
    const actual = existsSync(file) ? readFileSync(file, "utf8") : undefined;
    if (actual === expected) continue;
    const a = (actual ?? "").split("\n");
    const e = expected.split("\n");
    let line = 0;
    while (line < e.length && a[line] === e[line]) line++;
    out.push({
      file,
      line: line + 1,
      rule: "ui-slots-stale",
      message:
        actual === undefined
          ? `${rel} is missing; run pnpm gen:ui-slots`
          : `${rel} differs from the SDK slot catalog; run pnpm gen:ui-slots (never edit it by hand)`,
    });
  }
  return out;
}
